fn reverse(v: &mut Vec<u64>) {
    let n = v.len();
    if n < 2 {
        return;
    }

    let mut left: usize = 0;
    let mut right: usize = n - 1;

    while left < right {
        v.swap(left, right);
        left += 1;
        right -= 1;
    }
}